const input = $input.first().json;
const poLineKey = $('1_Triggered by Another Workflow').first().json.po_line_key;

// Row exists if it has a po_line_key that matches
const exists = (input.po_line_key !== undefined && 
               input.po_line_key !== null && 
               input.po_line_key !== '') ? 'true' : 'false';

return [{
  json: {
    row_exists: exists,
    po_line_key: poLineKey
  }
}];

const po = $('1_Triggered by Another Workflow').first().json;
const band = $('6_Read - Band Config').first().json;
const client = $('7_Read - Client Config').first().json;

// Get Communication Logs row - may be freshly created or existing
// We re-read it after creation to get current state
const logs = $('2b_Read - Communication Logs Row').first().json;

const testMode = client.test_mode === true || client.test_mode === 'true' || client.test_mode === 'TRUE';

// Calculate ship_by_date as a Date object
const shipByDate = new Date(po.ship_by_date);
const issueDate = new Date(po.issue_date);

// Total window in calendar days
const totalWindowDays = Math.round((shipByDate - issueDate) / (1000 * 60 * 60 * 24));

// Stage 2 and Stage 3 start thresholds
const s2StartsDaysBefore = parseInt(band['S2 starts N working days before ship-by']) || 0;
const s3StartsDaysBefore = parseInt(band['S3 starts N working days before ship-by']) || 0;

return [{
  json: {
    // PO fields
    po_line_key: po.po_line_key,
    po_number: po.po_number,
    po_line_item: po.po_line_item,
    supplier_code: po.supplier_code,
    issue_date: po.issue_date,
    ship_by_date: po.ship_by_date,
    ship_by_band: po.ship_by_band,

    // Band fields
    s2_starts_days_before_shipby: s2StartsDaysBefore,
    s3_starts_days_before_shipby: s3StartsDaysBefore,

    // Client fields
    test_mode: testMode,

    // Computed
    total_window_days: totalWindowDays,

    // Communication Logs current state
    // Communication Logs current state
    follow_up_stage: logs.follow_up_stage || 'Stage1',
    follow_up_status: logs.follow_up_status || '',
    stage1_outreach_timestamp: logs.stage1_outreach_timestamp || '',
    stage2_internal_escalation_sent: logs.stage2_internal_escalation_sent || '',
    stage2_acknowledgment_sent: logs.stage2_acknowledgment_sent || '',
    stage2_fully_escalated: logs.stage2_fully_escalated || '',
  }
}];

const ctx = $input.first().json;
const currentStage = ctx.follow_up_stage;
const testMode = ctx.test_mode;
const now = new Date();

// Helper: production mode date threshold check
// Returns true if today >= ship_by_date - N days
function isDateThresholdReached(shipByDateStr, daysBeforeShipBy) {
  const shipBy = new Date(shipByDateStr);
  const threshold = new Date(shipBy);
  threshold.setDate(threshold.getDate() - daysBeforeShipBy);
  threshold.setHours(0, 0, 0, 0);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return today >= threshold;
}

// Helper: test mode threshold check
// Returns true if minutes elapsed since stage1_outreach_timestamp >= 
// (total_window_days - daysBeforeShipBy)
function isTestThresholdReached(stage1OutreachTimestamp, totalWindowDays, daysBeforeShipBy) {
  if (!stage1OutreachTimestamp) return false;
  const outreachTime = new Date(stage1OutreachTimestamp);
  const minutesElapsed = (now - outreachTime) / (1000 * 60);
  const thresholdMinutes = totalWindowDays - daysBeforeShipBy;
  return minutesElapsed >= thresholdMinutes;
}

let newStage = null;
let newStatus = null;

// Transition 1: Stage1 -> Stage1.5
if (currentStage === 'Stage1') {
  const exhausted = 
    ['Escalation_Sent', 'Acknowledgment_Sent', 'Acknowledgment_Not_Applicable'].includes(ctx.follow_up_status);

  if (exhausted) {
    newStage = 'Stage1.5';
    newStatus = 'Monitoring_Reply';
  }
}

// Transition 2: Stage1.5 -> Stage2
else if (currentStage === 'Stage1.5') {
  const thresholdReached = testMode
    ? isTestThresholdReached(ctx.stage1_outreach_timestamp, ctx.total_window_days, ctx.s2_starts_days_before_shipby)
    : isDateThresholdReached(ctx.ship_by_date, ctx.s2_starts_days_before_shipby);

  if (thresholdReached) {
    newStage = 'Stage2';
    newStatus = 'Stage_Initiated';
  }
}

// Transition 3: Stage2 -> Stage2.5
else if (currentStage === 'Stage2') {
  const exhausted = 
    ['Escalation_Sent', 'Acknowledgment_Sent', 'Acknowledgment_Not_Applicable'].includes(ctx.follow_up_status);

  if (exhausted) {
    newStage = 'Stage2.5';
    newStatus = 'Monitoring_Reply';
  }
}

// Transition 4: Stage2.5 -> Stage3
else if (currentStage === 'Stage2.5') {
  const thresholdReached = testMode
    ? isTestThresholdReached(ctx.stage1_outreach_timestamp, ctx.total_window_days, ctx.s3_starts_days_before_shipby)
    : isDateThresholdReached(ctx.ship_by_date, ctx.s3_starts_days_before_shipby);

  if (thresholdReached) {
    newStage = 'Stage3';
    newStatus = 'Stage_Initiated';
  }
}

// No transition needed
const transitionNeeded = newStage !== null;

return [{
  json: {
    ...ctx,
    transition_needed: transitionNeeded,
    new_stage: newStage,
    new_status: newStatus,
  }
}];

const po = $('2a_Read - All Open POs').first().json;
const trigger = $('1_Triggered by Another Workflow').first().json;

return [{
  json: {
    po_line_key: trigger.po_line_key,
    client_code: po.client_code,
    client_company_name: po.client_company_name,
    comms_group_id: po.comms_group_id,
    po_number: po.po_number,
    supplier_code: po.supplier_code,
    supplier_name: po.supplier_name,
    po_line_item: po.po_line_item,
    material_code: po.material_code,
    material_name: po.material_name,
    follow_up_stage: 'Stage1',
    follow_up_status: 'Stage_Initiated',
    last_action_timestamp: new Date().toISOString(),
  }
}];

const ctx = $('9_Determine - Stage Transition').first().json;

return [{
  json: {
    po_line_key: ctx.po_line_key,
    follow_up_stage: ctx.new_stage,
    follow_up_status: ctx.new_status,
    last_action_timestamp: new Date().toISOString(),
  }
}];
